// types
import { Opening } from "../types";

// Opening book generated by `npm run build-openings` from lichess-org/chess-openings (CC0).
// Matching is on FEN piece placement only, so transpositions are recognised.
interface RawOpeningBook {
    openings: [eco: string, name: string][];
    positions: Record<string, number>;
}

export type OpeningLookup = (fen: string) => Opening | undefined;

let bookPromise: Promise<OpeningLookup> | null = null;

// The book is ~650 KB, so it's code-split into its own chunk and fetched on first use.
export const loadOpeningBook = (): Promise<OpeningLookup> => {
    bookPromise ??= import(/* webpackChunkName: "openings" */ "../constants/openings.json")
        .then((module) => {
            const book = (module.default ?? module) as unknown as RawOpeningBook;
            return (fen: string) => {
                const index = book.positions[fen.split(" ")[0]];
                if (index === undefined) return undefined;
                const [eco, name] = book.openings[index];
                return { eco, name };
            };
        })
        .catch((err) => {
            bookPromise = null; // allow a retry next time
            throw err;
        });
    return bookPromise;
};
